CREATE   TRIGGER dbo.tr_actual_break_payroll_frozen ON dbo.attendance_breaks AFTER INSERT,UPDATE,DELETE AS
BEGIN
 SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM(SELECT attendance_id FROM inserted UNION SELECT attendance_id FROM deleted)x
  JOIN dbo.attendance_records a ON a.attendance_id=x.attendance_id
  JOIN dbo.payroll_periods p WITH(UPDLOCK,HOLDLOCK) ON p.period_start<=a.work_date AND p.period_end>a.work_date
