CREATE   TRIGGER dbo.tr_contracts_keep_history ON dbo.contracts AFTER UPDATE AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (
        SELECT 1 FROM inserted i JOIN deleted d ON d.contract_id=i.contract_id
        WHERE i.employee_id<>d.employee_id OR i.contract_type_id<>d.contract_type_id
           OR i.contract_number<>d.contract_number OR i.signed_date<>d.signed_date
           OR i.start_date<>d.start_date
           OR (d.end_date IS NOT NULL AND (i.end_date IS NULL OR i.end_date>d.end_date))
           OR (i.end_date IS NOT NULL AND i.end_date<i.start_date)
    ) THROW 51011, N'Signed contract contents are immutable; renewal requires a new contract.', 1;
END;

