CREATE   TRIGGER dbo.tr_overtime_no_self_approval ON dbo.overtime_requests AFTER INSERT,UPDATE AS
 BEGIN SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.accounts a ON a.account_id=i.processed_by WHERE a.employee_id=i.employee_id)
  THROW 51009,N'Khong tu duyet tang ca.',1;
 IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.overtime_id=i.overtime_id WHERE i.employee_id<>d.employee_id OR
  (d.status<>'CHO_DUYET' AND (i.requested_start<>d.requested_start OR i.requested_end<>d.requested_end OR i.reason<>d.reason
   OR ISNULL(i.processed_by,0)<>ISNULL(d.processed_by,0) OR ISNULL(i.processed_at,'19000101')<>ISNULL(d.processed_at,'19000101')
   OR ISNULL(i.rejection_reason,N'')<>ISNULL(d.rejection_reason,N'') OR
   (i.status<>d.status AND NOT(d.status='DA_DUYET' AND i.status='DA_HUY' AND d.actual_start IS NULL AND d.actual_end IS NULL AND d.confirmed_by IS NULL)))))
  THROW 51010,N'Khong doi chu hoac ket qua duyet tang ca da xu ly.',1; END;

